# Generator: renders every spec/ksy/*.ksy into src-tauri/crates/schema/src/gen/ and rewrites gen/mod.rs.
# Usage: python tools/ksc_gen.py  (run from the repository root)
# Generated files must not be edited by hand; change the .ksy instead.
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
KSC = ROOT / "tools" / "kaitai-struct-compiler-0.11" / "bin" / "kaitai-struct-compiler.bat"
KSY_DIR = ROOT / "spec" / "ksy"
OUT_DIR = ROOT / "src-tauri" / "crates" / "schema" / "src" / "gen"
HEADER = "// Generated by ksc; do not edit. Re-run `python tools/ksc_gen.py` after changing a .ksy.\n"


def main() -> int:
    if not KSC.exists():
        print(f"ksc not found: {KSC}", file=sys.stderr)
        return 1
    ksys = sorted(KSY_DIR.glob("*.ksy"))
    if not ksys:
        print(f"no .ksy under {KSY_DIR}", file=sys.stderr)
        return 1
    for ksy in ksys:
        cmd = [str(KSC), "-t", "rust", "--outdir", str(OUT_DIR), str(ksy)]
        print(" ".join(cmd))
        rc = subprocess.call(cmd)
        if rc != 0:
            return rc
    mods = "".join(f"pub mod {k.stem};\n" for k in ksys)
    (OUT_DIR / "mod.rs").write_text(HEADER + mods, encoding="utf-8", newline="\n")
    print(f"wrote {OUT_DIR / 'mod.rs'} ({len(ksys)} modules)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
